?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>V16.5 Jessica Intelligence Connector</title><style>body{margin:0;background:#f5f3ef;color:#111;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.header{background:#111827;color:white;padding:30px}.brand{font-family:Georgia,serif;color:#c8a96e;font-size:38px}.wrap{max-width:1800px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.kpi,.panel{background:#fff;border-radius:16px;box-shadow:0 2px 12px #0001}.kpi{padding:18px}.n{font-size:28px;font-weight:900}.panel{margin-top:18px;overflow:hidden}.panel h2{font-family:Georgia,serif;margin:0;padding:18px;border-bottom:1px solid #eee}.btn{border:0;background:#c8a96e;color:#111;padding:9px 11px;border-radius:9px;font-weight:900;font-size:12px;margin:2px;text-decoration:none;display:inline-block}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #eee;vertical-align:top;font-size:14px}th{font-size:11px;color:#777;text-transform:uppercase;background:#faf9f6}.muted{color:#777;font-size:13px}pre{white-space:pre-wrap;background:#111;color:#fff;padding:14px;border-radius:12px;overflow:auto}@media(max-width:1000px){.grid{grid-template-columns:1fr}.wrap{padding:14px}}</style></head><body><div class="header"><div class="brand">V16.5 Jessica Intelligence Connector</div><div>Bridge between Retell voice and Jessica’s website/Supabase intelligence.</div></div><main class="wrap"><p><a class="btn" target="_blank" href="<?=h($test)?>">Run Test Context</a></p><section class="grid"><div class="kpi"><div class="n"><?=h($stats['sessions'])?></div>Sessions</div><div class="kpi"><div class="n"><?=h($stats['valuation'])?></div>Valuation</div><div class="kpi"><div class="n"><?=h($stats['seller'])?></div>Seller</div><div class="kpi"><div class="n"><?=h($stats['buyer'])?></div>Buyer</div><div class="kpi"><div class="n"><?=h($stats['executive'])?></div>Executive</div></section><section class="panel"><h2>Retell Function URL</h2><div style="padding:16px"><pre>https://markpires.com/lead-engine/retell/jessica-context.php?key=timetomakethedonuts</pre><div class="muted">Pass phone/from_number, call_id, lead_source, name, address, email, utterance when available.</div></div></section><section class="panel"><h2>Recent Voice Context Sessions</h2><table><tr><th>Time</th><th>Mode</th><th>Lead</th><th>Source</th><th>Opening Script</th><th>Scores</th></tr><?php foreach($sessions as $s):?><tr><td><?=h($s['created_at'])?></td><td><strong><?=h($s['mode'])?></strong><div class="muted"><?=h($s['phone'])?></div></td><td><?=h($s['lead_name'])?><div class="muted"><?=h($s['lead_address'])?><br><?=h($s['town'])?></div></td><td><?=h($s['lead_source'])?><div class="muted"><?=h($s['lead_type'])?></div></td><td><?=h($s['opening_script'])?></td><td>Lead <?=h($s['lead_score'])?><br>Opp <?=h($s['opportunity_score'])?><br>$<?=number_format((float)$s['estimated_commission'],0)?></td></tr><?php endforeach;?></table></section><section class="panel"><h2>Executive Voice Commands</h2><table><tr><th>Time</th><th>Phone</th><th>Command</th><th>Response</th></tr><?php foreach($commands as $c):?><tr><td><?=h($c['created_at'])?></td><td><?=h($c['phone'])?></td><td><?=h($c['command_text'])?></td><td><?=h($c['response_summary'])?></td></tr><?php endforeach;?></table></section></main></body></html>
